[CmdletBinding()]
param([string]$SkillRoot = (Join-Path (Get-Location) '.agents/skills/es-game-core-loop-validation'))
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $SkillRoot '..\..\..')).Path;$report=Join-Path $SkillRoot 'worker-isolation-fixture.json';$outDir=Join-Path $root 'ES/Output/StaticReplay';$before=@(Get-ChildItem $outDir -Filter 'worker-request-*.json' -File -ErrorAction SilentlyContinue)+@(Get-ChildItem $outDir -Filter 'worker-response-*.json' -File -ErrorAction SilentlyContinue)
try{$r=& powershell -NoProfile -File (Join-Path $root 'ES/Automation/ABCD/Test-ESABCDWorkerRuntime.ps1') -ProjectRoot $root -ReportPath $report|ConvertFrom-Json;if($r.status -ne 'passed' -or $r.runtimeStatus -ne 'worker-process-passed' -or [int]$r.failedCount -ne 0){throw 'WORKER_PROCESS_ISOLATION_FAILED'};[ordered]@{status='passed';runtimeStatus=$r.runtimeStatus;requestCount=$r.requestCount;passedCount=$r.passedCount;failedCount=$r.failedCount;processIsolation=$true}|ConvertTo-Json}finally{if(Test-Path -LiteralPath $report){Remove-Item -LiteralPath $report -Force};$after=@(Get-ChildItem $outDir -Filter 'worker-request-*.json' -File -ErrorAction SilentlyContinue)+@(Get-ChildItem $outDir -Filter 'worker-response-*.json' -File -ErrorAction SilentlyContinue);foreach($f in $after){if(-not @($before|Where-Object FullName -eq $f.FullName)){Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue}}}
